{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-plugin-timer",
  "version": "0.1.0",
  "description": "OpenCode V2 server plugin: per-session repeating or one-shot timers that inject synthetic reminders",
  "type": "module",
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "clean": "node -e \"require('node:fs').rmSync('dist', { recursive: true, force: true })\"",
    "build": "npm run clean && tsc -p tsconfig.build.json",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "check": "bun run typecheck && bun test",
    "prepack": "npm run build",
    "prepublishOnly": "npm run check",
    "pack:check": "npm pack --dry-run",
    "release:dry": "npm publish --dry-run",
    "release": "npm publish"
  },
  "dependencies": {
    "@opencode/plugin": "2.1.4",
    "node-cron": "^4.6.0"
  },
  "devDependencies": {
    "bun-types": "latest",
    "typescript": "^5.6.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "timer",
    "reminder",
    "synthetic",
    "steer",
    "cron"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bendtherules/opencode-plugin-timer.git"
  },
  "homepage": "https://github.com/bendtherules/opencode-plugin-timer",
  "bugs": {
    "url": "https://github.com/bendtherules/opencode-plugin-timer/issues"
  },
  "author": "bendtherules",
  "publishConfig": {
    "access": "public"
  }
}
